('advanced-native-711', '["phrase"]'::jsonb, '{"advanced-native-711-v1-audio":{"type":"mc","answers":["By automatically following other people’s expected pattern."],"options":["By automatically following other people’s expected pattern.","By considering personal interests alongside advice.","By comparing course requirements before choosing.","By asking what different jobs involve."]},"advanced-native-711-v2-reply":{"type":"mc","answers":["I needed a route that allowed me to work while studying.","I wanted to choose for myself rather than follow a script.","The practical course suited the work I hoped to do.","I compared several routes and found one that fitted my interests."],"options":["I needed a route that allowed me to work while studying.","I wanted to choose for myself rather than follow a script.","The practical course suited the work I hoped to do.","I compared several routes and found one that fitted my interests."]},"advanced-native-711-v1-scene":{"type":"mc","answers":["She seems to be following a script."],"options":["She seems to be following a script.","She has carefully compared her interests with all options.","She has chosen a route nobody expected after researching it herself."]},"advanced-native-711-v1-contrast":{"type":"mc","answers":["A learner chooses a popular route after careful research because it genuinely fits personal goals."],"options":["A learner chooses a popular route after careful research because it genuinely fits personal goals.","Someone accepts a role solely because everyone assumes it is the usual next step.","A learner copies the expected route without considering personal reasons."]},"advanced-native-711-v1-branch":{"type":"mc","answers":["Not necessarily. Following a script is about relying on expectations without your own choice, not simply choosing a popular course."],"options":["Keep the popular choice without checking whether its content matches what you want to learn.","Not necessarily. Following a script is about relying on expectations without your own choice, not simply choosing a popular course.","Choose a less popular course just so your decision looks different."]},"advanced-native-711-v1-final":{"type":"open","answers":["I do not want to follow a script without considering my options. I will compare university courses with paid apprenticeships.","Rather than following a script, I want to check which route suits my goals. I can listen to my family and still make my own choice."],"options":[]}}'::jsonb),
('advanced-native-712', '["phrase"]'::jsonb, '{"advanced-native-712-v1-audio":{"type":"mc","answers":["It serves as a personal cue to change mental focus."],"options":["It shows the speaker was already studying before the cue.","It serves as a personal cue to change mental focus.","It guarantees perfect concentration for everyone.","It replaces the need to understand the lesson."]},"advanced-native-712-v2-reply":{"type":"mc","answers":["It acts as a psychological switch and helps me feel ready to practise.","It marks the end of my workday.","I like starting practice with a small routine.","Comfortable clothes make the session easier for me."],"options":["It acts as a psychological switch and helps me feel ready to practise.","It marks the end of my workday.","I like starting practice with a small routine.","Comfortable clothes make the session easier for me."]},"advanced-native-712-v1-scene":{"type":"mc","answers":["Putting my phone away acts as a psychological switch for me."],"options":["Putting my phone away acts as a psychological switch for me.","Putting a phone away guarantees that nobody ever feels distracted.","The routine means I no longer need a work plan."]},"advanced-native-712-v1-contrast":{"type":"mc","answers":["The same cue must remove all stress for every person."],"options":["A familiar routine can signal a change of activity for someone.","The same cue must remove all stress for every person.","A person may describe a sudden shift in focus using the metaphor."]},"advanced-native-712-v1-branch":{"type":"mc","answers":["It may act as a psychological switch for you without removing every nervous feeling."],"options":["Still feeling nervous proves the routine cannot have helped your focus at all.","It may act as a psychological switch for you without removing every nervous feeling.","Treat the ready feeling as if you had already rehearsed the presentation content."]},"advanced-native-712-v1-final":{"type":"open","answers":["Putting away my work things