('advanced-native-713', '["phrase"]'::jsonb, '{"advanced-native-713-v1-audio":{"type":"mc","answers":["She appears more comfortable with who she is."],"options":["She is guaranteed never to feel nervous again.","She has changed her accent to match everyone else’s.","She appears more comfortable with who she is.","She has stopped learning anything new."]},"advanced-native-713-v2-reply":{"type":"mc","answers":["I am less worried about pretending to be someone else.","I can share my interests without apologising for them.","I feel accepted even when my tastes differ from the group’s.","I feel more at ease in my own skin."],"options":["I am less worried about pretending to be someone else.","I can share my interests without apologising for them.","I feel accepted even when my tastes differ from the group’s.","I feel more at ease in my own skin."]},"advanced-native-713-v1-scene":{"type":"mc","answers":["She is more at ease in her own skin."],"options":["She is more at ease in her own skin.","She has decided that personal growth no longer matters.","She only feels accepted when every interest matches everyone else’s."]},"advanced-native-713-v1-contrast":{"type":"mc","answers":["They must never feel nervous or want to improve any skill."],"options":["They do not feel a need to hide every difference.","They feel comfortable with their own identity.","They must never feel nervous or want to improve any skill."]},"advanced-native-713-v1-branch":{"type":"mc","answers":["You can be at ease in your own skin and still feel nervous about a new situation."],"options":["Hide your personal interest again, since feeling nervous must mean you should not mention it.","Avoid practising answers so that nothing about your presentation changes.","You can be at ease in your own skin and still feel nervous about a new situation."]},"advanced-native-713-v1-final":{"type":"open","answers":["I feel more at ease in my own skin now and no longer hide my taste in music. My friends listen with inter