('advanced-native-714', '["phrase"]'::jsonb, '{"advanced-native-714-v1-audio":{"type":"mc","answers":["They organised different contributions into one performance."],"options":["They cancelled the performance before gathering any material.","They kept the poems, music and photos unrelated and unused.","They attended an existing show without preparing anything.","They organised different contributions into one performance."]},"advanced-native-714-v2-reply":{"type":"mc","answers":["I will keep the instructions brief and clear.","I will check the details with the coordinator before sending it.","I will put together a short guide with a map and key contacts.","I will ask each team for the information newcomers need."],"options":["I will keep the instructions brief and clear.","I will check the details with the coordinator before sending it.","I will put together a short guide with a map and key contacts.","I will ask each team for the information newcomers need."]},"advanced-native-714-v1-scene":{"type":"mc","answers":["I put together a report from the group’s work."],"options":["I received the finished report and made no contribution to assembling it.","I put together a report from the group’s work.","I discarded the material without using it."]},"advanced-native-714-v1-contrast":{"type":"mc","answers":["Leaving all the parts separate without making a plan or finished object."],"options":["Leaving all the parts separate without making a plan or finished object.","Combining notes and pictures into a clear display.","Organising several contributions into a school show."]},"advanced-native-714-v1-branch":{"type":"mc","answers":["Let us put the report together by choosing an order and linking the sections."],"options":["Let us put the report together by choosing an order and linking the sections.","Having the files somewhere means the report is already assembled.","Delete the sections before deciding how they could fit."]},"advanced-native-714-v1-final":{"type":"open","ans