('advanced-native-715', '["phrase"]'::jsonb, '{"advanced-native-715-v1-audio":{"type":"mc","answers":["She appeared more confident."],"options":["She appeared more confident.","She was simply receiving more attention, without feeling more willing to speak.","She had stopped needing any further practice.","She had become less willing to share ideas."]},"advanced-native-715-v2-reply":{"type":"mc","answers":["I felt proud that the group understood my examples.","It made me walk taller because I realised I could explain things clearly.","I became more willing to answer questions.","It helped me trust my preparation a little more."],"options":["I felt proud that the group understood my examples.","It made me walk taller because I realised I could explain things clearly.","I became more willing to answer questions.","It helped me trust my preparation a little more."]},"advanced-native-715-v1-scene":{"type":"mc","answers":["She seems to walk taller after the session."],"options":["She is now ready to lead the next workshop without any support.","She seems to walk taller after the session.","She has withdrawn from every discussion since the session."]},"advanced-native-715-v1-contrast":{"type":"mc","answers":["Someone takes quicker steps to catch a bus, with no information about confidence."],"options":["A volunteer begins offering ideas after realising a contribution was useful.","A learner speaks with more confidence after a successful task.","Someone takes quicker steps to catch a bus, with no information about confidence."]},"advanced-native-715-v1-branch":{"type":"mc","answers":["It sounds as if you walk taller now, and you can still keep developing your skills."],"options":["Wait for another compliment before deciding whether you feel ready to speak again.","It sounds as if you walk taller now, and you can still keep developing your skills.","Offer to train the next group of guides unaided after this one successful tour."]},"advanced-native-715-v1-final":{"type":"open