('advanced-native-718', '["phrase"]'::jsonb, '{"advanced-native-718-v1-audio":{"type":"mc","answers":["Their routines differ greatly despite living near each other."],"options":["Their homes must be in distant countries.","Their routines are almost identical.","They cannot speak to each other because their routines differ.","Their routines differ greatly despite living near each other."]},"advanced-native-718-v2-reply":{"type":"mc","answers":["The class sizes are very different.","They suit different ways of learning.","They are worlds apart in teaching style.","One is mostly practical, while the other focuses on theory."],"options":["The class sizes are very different.","They suit different ways of learning.","They are worlds apart in teaching style.","One is mostly practical, while the other focuses on theory."]},"advanced-native-718-v1-scene":{"type":"mc","answers":["The two restaurants are worlds apart in atmosphere."],"options":["The two restaurants are worlds apart in atmosphere.","The two restaurants have exactly the same atmosphere.","The two restaurants must be far apart geographically."]},"advanced-native-718-v1-contrast":{"type":"mc","answers":["Their methods and experiences are almost identical, with only a tiny wording change."],"options":["Their methods and experiences are almost identical, with only a tiny wording change.","Their approaches to teaching differ greatly.","Their daily responsibilities have very little in common."]},"advanced-native-718-v1-branch":{"type":"mc","answers":["Our experiences may be worlds apart, but we can still listen and agree on a shared task."],"options":["Assume that the same technical words mean the same thing to both of you without checking.","Give both people identical tasks before asking what experience each brings.","Our experiences may be worlds apart, but we can still listen and agree on a shared task."]},"advanced-native-718-v1-final":{"type":"open","answers":["Our school routines are worlds apart, especially tra