('advanced-native-724', '["phrase"]'::jsonb, '{"advanced-native-724-v1-audio":{"type":"mc","answers":["It can look more formal or more casual with different items."],"options":["It suits every event regardless of its rules.","It can only be worn with jeans.","It can look more formal or more casual with different items.","It can only be styled for a formal outfit."]},"advanced-native-724-v2-reply":{"type":"mc","answers":["It folds easily and does not take much space.","I can wear it with the shoes I already have.","The fabric is comfortable in the weather I expect.","It can be dressed up or down, so I can use it for different plans."],"options":["It folds easily and does not take much space.","I can wear it with the shoes I already have.","The fabric is comfortable in the weather I expect.","It can be dressed up or down, so I can use it for different plans."]},"advanced-native-724-v1-scene":{"type":"mc","answers":["The jacket can be dressed up or down."],"options":["The jacket can be dressed up or down.","The same outfit is worn unchanged at the dinner and on the walk.","The jacket can only work with one fixed outfit."]},"advanced-native-724-v1-contrast":{"type":"mc","answers":["An item that can be dressed up or down is automatically suitable for every occasion."],"options":["An item that can be dressed up or down is automatically suitable for every occasion.","Accessories can change how formal an outfit looks.","The same item may work in more than one style."]},"advanced-native-724-v1-branch":{"type":"mc","answers":["It can be dressed up or down, but we should still check the event’s dress code."],"options":["It can be dressed up or down, but we should still check the event’s dress code.","Keep the casual trainers and assume the jacket makes them acceptable at this ceremony.","Change the scarf and stop checking whether the ceremony requires formal shoes."]},"advanced-native-724-v1-final":{"type":"open","answers":["My plain shirt can be dressed up or down with trouse